import type { ActionContext } from '../../data/action_context'
import type { ActionDefinition } from '../../data/action_types'

const FOLDER_PLACEHOLDER_NAMES = 'active-cards-folder|worktree-folder|repository-folder|project-folder|releases-folder'
const CARD_PLACEHOLDER_NAMES = 'card-file|card-title|card-prompt'
const CONFLICT_PLACEHOLDER_NAMES = 'conflict-file|conflict-files'
const PLACEHOLDER_PATTERN = new RegExp(`\\{\\{\\s*(${FOLDER_PLACEHOLDER_NAMES}|${CARD_PLACEHOLDER_NAMES}|${CONFLICT_PLACEHOLDER_NAMES})\\s*\\}\\}`, 'gu')
const CARD_PROMPT_PLACEHOLDER_PATTERN = /\{\{\s*card-prompt\s*\}\}/u

export interface ActionFolderPlaceholderValues {
    activeCardsFolder: string
    projectFolder: string
    repositoryFolder: string
    releasesFolder: string
    worktreeFolder: string
}

export function resolvePlaceholders(
    text: string,
    context: ActionContext,
    folders: ActionFolderPlaceholderValues,
    extraPrompt: string,
): string {
    return text.replace(PLACEHOLDER_PATTERN, (_match, name: string) => {
        if (name === 'active-cards-folder') {
            if (!folders.activeCardsFolder) throw new Error('Cannot resolve active-cards-folder without a configured working folder')

            return folders.activeCardsFolder
        }
        if (name === 'worktree-folder') {
            if (!folders.worktreeFolder) throw new Error('Cannot resolve worktree-folder without a run checkout path')

            return folders.worktreeFolder
        }
        if (name === 'repository-folder') {
            if (!folders.repositoryFolder) throw new Error('Cannot resolve repository-folder without an opened repository path')

            return folders.repositoryFolder
        }
        if (name === 'project-folder') {
            if (!folders.projectFolder) throw new Error('Cannot resolve project-folder without a configured project path')

            return folders.projectFolder
        }
        if (name === 'releases-folder') {
            if (!folders.releasesFolder) throw new Error('Cannot resolve releases-folder without a configured releases folder')

            return folders.releasesFolder
        }

        if (name === 'card-prompt') return extraPrompt
        if (name === 'conflict-file') {
            if (!context.conflictFile) throw new Error('Cannot resolve conflict-file placeholder without a selected conflict file')

            return context.conflictFile
        }
        if (name === 'conflict-files') {
            if (!context.conflictFiles) throw new Error('Cannot resolve conflict-files placeholder without conflict files')

            return context.conflictFiles
        }

        if (name === 'card-title') {
            if (!context.title) throw new Error('Cannot resolve card-title placeholder without a card title')

            return context.title
        }

        if (!context.file) throw new Error('Cannot resolve card-file placeholder without a file context')

        return context.file
    })
}

export function resolveAgentPrompt(
    action: ActionDefinition,
    context: ActionContext,
    folders: ActionFolderPlaceholderValues,
    extraPrompt: string,
): string {
    if (!action.prompt) throw new Error(`Missing prompt for agent action "${action.label}"`)
    const resolvedText = resolvePlaceholders(action.prompt, context, folders, extraPrompt)
    if (CARD_PROMPT_PLACEHOLDER_PATTERN.test(action.prompt)) return resolvedText
    if (extraPrompt.trim().length === 0) return resolvedText

    return `${resolvedText}\n\n${extraPrompt}`
}

import { IconButton, ListItemIcon, MenuItem, Stack, Tooltip } from '@mui/material'
import { useEffect, useMemo, useState } from 'react'
import type { MouseEvent } from 'react'
import { displayActionsForContext, type ActionContext } from '../../../../data/action_context'
import type { ActionDefinition } from '../../../../data/action_types'
import { dialogService } from '../../../../services/dialog_service'
import { useActions } from '../../../hooks/use_actions'
import { useRunningActionForContext } from '../../../hooks/use_action_runs'
import { ActionIcon } from './action_icon'
import { resolveActionIcon, type ActionIconSource } from './action_icon_resolver'
import { ActionPopup } from '../popup/action_popup'
import { useProjectReadOnly } from '../../../hooks/use_project_read_only'

/** How action entry points are rendered in an existing toolbar or menu. */
export type ActionEntryVariant = 'icons' | 'menuItems'
export type ActionEntryVisibility = 'all-matching' | 'explicit-context'

interface ActionEntryPointsProps {
    context: ActionContext
    onMenuItemSelected?: () => void
    popupAnchorElement?: HTMLElement | null
    variant: ActionEntryVariant
    visibility?: ActionEntryVisibility
}

const DEFAULT_ICON_SOURCE: ActionIconSource = { dataUri: null }

interface ActionPopupState {
    actionId: string
    anchorElement: HTMLElement
}

/**
 * Context-sensitive action entry points shown close to a card/file/folder. Filters
 * the loaded actions by `appliesTo`, and on activation opens a resizable popup bound
 * to the action and context. `before`/`after` shortcuts push a new popup for the
 * related action with the same context.
 */
export function ActionEntryPoints(props: ActionEntryPointsProps) {
    const { context, onMenuItemSelected, popupAnchorElement, variant, visibility = 'all-matching' } = props
    const { actions: loadedActions } = useActions()
    const runningRun = useRunningActionForContext(context)
    const readOnly = useProjectReadOnly()
    const runDisabled = readOnly || !!runningRun
    const [iconSources, setIconSources] = useState<Record<string, ActionIconSource>>({})
    const [popupState, setPopupState] = useState<ActionPopupState | null>(null)

    const matching = useMemo(() => {
        const contextActions = displayActionsForContext(loadedActions, context)
        if (visibility === 'explicit-context') {
            return contextActions.filter((action) => action.appliesTo?.kind === context.kind)
        }

        return contextActions
    }, [context, loadedActions, visibility])

    useEffect(() => {
        let isActive = true

        const loadIcons = async () => {
            const entries = await Promise.all(matching.map(async (action) => [action.id, await resolveActionIcon(action.icon)] as const))
            if (!isActive) return

            setIconSources(Object.fromEntries(entries))
        }

        void loadIcons()

        return () => {
            isActive = false
        }
    }, [matching])

    if (matching.length === 0) return null

    const open = (actionId: string, anchorElement: HTMLElement) => {
        onMenuItemSelected?.()
        setPopupState({ actionId, anchorElement })
    }

    const handleOpen = (event: MouseEvent<HTMLElement>) => {
        try {
            const { actionId } = event.currentTarget.dataset
            if (!actionId) throw new Error('Missing action id on action entry point')

            open(actionId, popupAnchorElement ?? event.currentTarget)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Action popup could not be opened' })
        }
    }

    const iconSourceFor = (action: ActionDefinition) => iconSources[action.id] ?? DEFAULT_ICON_SOURCE

    const closePopup = () => {
        setPopupState(null)
    }

    const popup = popupState ? (
        <ActionPopup
            anchorElement={popupState.anchorElement}
            context={context}
            draggable
            initialActionId={popupState.actionId}
            key={popupState.actionId}
            onClose={closePopup}
        />
    ) : null

    const menuItems = (
        <>
            {matching.map((action) => (
                <MenuItem
                    data-action-id={action.id}
                    disabled={runDisabled}
                    key={action.id}
                    onClick={handleOpen}
                >
                    <ListItemIcon>
                        <ActionIcon fontSize="small" source={iconSourceFor(action)} />
                    </ListItemIcon>
                    {action.label}
                </MenuItem>
            ))}
            {popup}
        </>
    )

    if (variant === 'menuItems') return menuItems

    return (
        <Stack direction="row" spacing={0.25} sx={{ flexShrink: 0 }}>
            {matching.map((action) => (
                <Tooltip key={action.id} title={action.label}>
                    <IconButton
                        aria-label={action.label}
                        data-action-id={action.id}
                        disabled={runDisabled}
                        onClick={handleOpen}
                        size="small"
                    >
                        <ActionIcon fontSize="small" source={iconSourceFor(action)} />
                    </IconButton>
                </Tooltip>
            ))}
            {popup}
        </Stack>
    )
}

const { spawn } = require('node:child_process');
const { assertGitRoot, requireRootPath } = require('../../git/git_commands');
const { ActionCancellationError } = require('./action_cancellation_error');
const { resolvePlaceholders } = require('./action_text');

async function runCommand(project, command, signal, onOutput, spawnCommand = spawn) {
    const rootPath = requireRootPath(project);
    await assertGitRoot(rootPath);
    if (signal.aborted) throw new ActionCancellationError('Action cancelled');

    return new Promise((resolve, reject) => {
        const child = spawnCommand(command, { cwd: rootPath, shell: true, signal });
        let stderr = '';
        let stdout = '';
        child.stdout.on('data', (chunk) => {
            const output = chunk.toString();
            stdout += output;
            onOutput({ stderr: '', stdout: output });
        });
        child.stderr.on('data', (chunk) => {
            const output = chunk.toString();
            stderr += output;
            onOutput({ stderr: output, stdout: '' });
        });
        child.on('error', (error) => {
            if (signal.aborted) reject(new ActionCancellationError('Action cancelled'));
            else reject(error);
        });
        child.on('close', (exitCode) => {
            if (signal.aborted) {
                reject(new ActionCancellationError('Action cancelled'));
                return;
            }

            resolve({ command, exitCode: exitCode ?? 1, stderr, stdout });
        });
    });
}

function executeCommandAction(input) {
    const command = resolvePlaceholders(
        input.action.command,
        input.context,
        input.project,
        input.primaryProject,
        input.projectFolder,
        input.releasesFolder,
        input.activeCardsFolder,
        input.extraPrompt,
    );
    const onOutput = ({ stderr, stdout }) => input.onOutput({ command, stderr, stdout });

    return input.commandRunner(input.project, command, input.signal, onOutput);
}

module.exports = { executeCommandAction, runCommand };

import { useId, useMemo, useState } from 'react'
import { displayActionsForContext, projectContextWithWorktree, type ActionContext } from '../../../../data/action_context'
import { dataService } from '../../../../services/data/data_service'
import { isReleasedCardActionContext, RELEASED_CARD_RUN_MESSAGE } from '../../../../../../shared/released_card_actions.mjs'
import { useActions } from '../../../hooks/use_actions'
import { useProjectState } from '../../../hooks/use_project_state'
import { useProjectActionWorktree } from '../../../hooks/use_worktrees'
import { ActionPopupContent } from './action_popup_content'

export { CARD_RUN_POPUP_SIZE_STORAGE_KEY, PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY } from './action_popup_content'

function resolvePopupTarget(context: ActionContext, snapshot: ReturnType<typeof useProjectState>['snapshot']) {
    if (context.kind === 'project') return 'Project'
    if (context.kind !== 'card') return null

    const cards = [...(snapshot?.activeCards ?? []), ...(snapshot?.backgroundCards ?? [])]

    return cards.find(({ header }) => header.internalId === context.cardInternalId)?.header.id ?? null
}

interface ActionPopupProps {
    anchorElement: HTMLElement | null
    context: ActionContext
    draggable?: boolean
    initialActionId?: string
    onActivate?: () => void
    onClose: () => void
    open?: boolean
    popupEntryId?: string
    stackPosition?: number
}

/** Universal action selector and run popup for the supplied context. */
export function ActionPopup(props: ActionPopupProps) {
    const { anchorElement, context, initialActionId, open } = props
    const { actions: loadedActions } = useActions()
    const { project, snapshot } = useProjectState()
    const projectActionWorktree = useProjectActionWorktree()
    const effectiveContext = useMemo(
        () => projectContextWithWorktree(context, projectActionWorktree),
        [context, projectActionWorktree],
    )
    const actions = useMemo(() => displayActionsForContext(loadedActions, effectiveContext), [effectiveContext, loadedActions])
    const [selectedActionId, setSelectedActionId] = useState<string | null>(initialActionId ?? actions[0]?.id ?? null)
    const [fullHeight, setFullHeight] = useState(false)
    const titleId = useId()
    // A run that edits its own card changes the context (state, title, worktree), so the
    // selected action can drop out of the filtered list mid-run. Keep it selectable instead
    // of closing the popup or silently switching to another action.
    const retainedAction = selectedActionId ? loadedActions.find(({ id }) => id === selectedActionId) ?? null : null
    const selectedAction = actions.find(({ id }) => id === selectedActionId) ?? retainedAction ?? actions[0] ?? null
    const selectableActions = selectedAction && !actions.some(({ id }) => id === selectedAction.id)
        ? [...actions, selectedAction]
        : actions
    const target = resolvePopupTarget(context, snapshot)
    const releasesFolder = dataService.getConfig()?.releasesFolder
    const readOnlyMessage = releasesFolder && isReleasedCardActionContext(effectiveContext, releasesFolder)
        ? RELEASED_CARD_RUN_MESSAGE
        : null

    const handleSelectAction = (actionId: string) => {
        setSelectedActionId(actionId)
    }

    const handleToggleFullHeight = () => setFullHeight((current) => !current)

    if (!selectedAction) return null

    return (
        <ActionPopupContent
            {...props}
            action={selectedAction}
            actions={selectableActions}
            assignmentContext={effectiveContext}
            baseContext={context}
            fullHeight={fullHeight}
            onSelectAction={handleSelectAction}
            onToggleFullHeight={handleToggleFullHeight}
            open={open ?? !!anchorElement}
            primaryPath={project?.rootPath ?? project?.id ?? null}
            readOnlyMessage={readOnlyMessage}
            target={target}
            titleId={titleId}
        />
    )
}

const path = require('node:path');
const { requireRootPath } = require('../../git/git_commands');

const FOLDER_PLACEHOLDER_NAMES = 'active-cards-folder|worktree-folder|repository-folder|project-folder|releases-folder';
const CARD_PLACEHOLDER_NAMES = 'card-file|this-card|card-title|card-prompt';
const CONFLICT_PLACEHOLDER_NAMES = 'conflict-file|conflict-files';
const PLACEHOLDER_PATTERN = new RegExp(`\\{\\{\\s*(${FOLDER_PLACEHOLDER_NAMES}|${CARD_PLACEHOLDER_NAMES}|${CONFLICT_PLACEHOLDER_NAMES})\\s*\\}\\}`, 'gu');
const CARD_PROMPT_PLACEHOLDER_PATTERN = /\{\{\s*card-prompt\s*\}\}/u;

function resolvePlaceholders(text, context, runProject, primaryProject, projectFolder, releasesFolder, activeCardsFolder, extraPrompt) {
    return text.replace(PLACEHOLDER_PATTERN, (_match, name) => {
        if (name === 'active-cards-folder') {
            if (typeof activeCardsFolder !== 'string' || activeCardsFolder.length === 0) {
                throw new Error('Cannot resolve active-cards-folder placeholder without a configured working folder');
            }

            return path.resolve(requireRootPath(primaryProject), activeCardsFolder);
        }
        if (name === 'worktree-folder') return requireRootPath(runProject);
        if (name === 'repository-folder') return requireRootPath(primaryProject);
        if (name === 'project-folder') {
            if (typeof projectFolder !== 'string') {
                throw new Error('Cannot resolve project-folder placeholder without a configured project folder');
            }

            const repositoryFolder = requireRootPath(primaryProject);

            return projectFolder.length === 0 ? repositoryFolder : path.resolve(repositoryFolder, projectFolder);
        }
        if (name === 'releases-folder') {
            if (typeof releasesFolder !== 'string' || releasesFolder.length === 0) {
                throw new Error('Cannot resolve releases-folder placeholder without a configured releases folder');
            }

            return path.resolve(requireRootPath(primaryProject), releasesFolder);
        }
        if (name === 'card-prompt') return extraPrompt;
        if (name === 'conflict-file') {
            if (!context.conflictFile) throw new Error('Cannot resolve conflict-file placeholder without a selected conflict file');

            return context.conflictFile;
        }
        if (name === 'conflict-files') {
            if (!context.conflictFiles) throw new Error('Cannot resolve conflict-files placeholder without conflict files');

            return context.conflictFiles;
        }
        if (name === 'card-title') {
            if (!context.title) throw new Error('Cannot resolve card-title placeholder without a card title');

            return context.title;
        }
        if (!context.file) throw new Error(`Cannot resolve ${name} placeholder without a file context`);

        return context.file;
    });
}

function resolveAgentPrompt(action, context, runProject, primaryProject, projectFolder, releasesFolder, activeCardsFolder, extraPrompt) {
    const prompt = resolvePlaceholders(
        action.prompt,
        context,
        runProject,
        primaryProject,
        projectFolder,
        releasesFolder,
        activeCardsFolder,
        extraPrompt,
    );
    if (CARD_PROMPT_PLACEHOLDER_PATTERN.test(action.prompt) || extraPrompt.trim().length === 0) return prompt;

    return `${prompt}\n\n${extraPrompt}`;
}

module.exports = { resolveAgentPrompt, resolvePlaceholders };

const { buildResumeAgentCommand, resolveAgentCommand } = require('../agent/agent_profiles.mjs');
const { normalizeConversationContext } = require('../agent/agent_transcript');
const { resolveAgentPrompt, resolvePlaceholders } = require('./action_text');

const CONTINUE_INPUT = 'continue';
function continuationReferencePath(reference) {
    return reference;
}

function withoutProviderConversationId(request) {
    return Object.fromEntries(Object.entries(request).filter(([fieldName]) => fieldName !== 'providerConversationId'));
}

function withoutConversation(result) {
    return Object.fromEntries(Object.entries(result).filter(([fieldName]) => fieldName !== 'conversation'));
}

function executionCommand(resolvedAgent, providerSession, streaming) {
    if (!providerSession) return resolvedAgent.command;
    if (!streaming || resolvedAgent.agent === 'claude') {
        return buildResumeAgentCommand(resolvedAgent.profile, providerSession.conversationId, resolvedAgent.command);
    }

    return resolvedAgent.command;
}

class ActionAgentExecutor {
    constructor(dependencies) {
        this.agentConfigProvider = dependencies.agentConfigProvider;
        this.agentRunnerService = dependencies.agentRunnerService;
        this.localGitService = dependencies.localGitService;
    }

    async execute(input) {
        const config = this.agentConfigProvider();
        const permissionMode = input.runInput.permissionMode ?? input.action.permissionMode;
        const thinkingLevel = input.runInput.thinkingLevel ?? input.action.thinkingLevel;
        const streaming = input.action.streaming;
        const resolvedAgent = resolveAgentCommand(config, {
            ...(input.runInput.agent ? { agent: input.runInput.agent } : (input.action.agent ? { agent: input.action.agent } : {})),
            ...(input.runInput.model ? { model: input.runInput.model } : (input.action.model ? { model: input.action.model } : {})),
            ...(permissionMode ? { permissionMode } : {}),
            ...(thinkingLevel ? { thinkingLevel } : {}),
        }, streaming);
        const sourceConversation = input.runInput.continueFrom
            ? await this.localGitService.loadAgentConversation(
                input.primaryProject,
                continuationReferencePath(input.runInput.continueFrom),
            )
            : null;
        const expectedCardInternalId = input.activityOrigin.kind === 'card' ? input.activityOrigin.cardInternalId : null;
        if (sourceConversation && sourceConversation.cardInternalId !== expectedCardInternalId) {
            throw new Error(`Agent conversation belongs to ${sourceConversation.cardInternalId}, not ${expectedCardInternalId}`);
        }

        const providerSession = sourceConversation?.providerSessions
            ?.find(({ agent }) => agent === resolvedAgent.agent) ?? null;
        const hasPromptOverride = Object.hasOwn(input.runInput, 'prompt');
        const prompt = hasPromptOverride
            ? resolvePlaceholders(
                input.runInput.prompt,
                input.context,
                input.project,
                input.primaryProject,
                input.projectFolder,
                input.releasesFolder,
                input.activeCardsFolder,
                input.runInput.extraPrompt,
            )
            : sourceConversation
                ? input.runInput.extraPrompt.trim().length > 0 ? input.runInput.extraPrompt : CONTINUE_INPUT
                : resolveAgentPrompt(
                    input.action,
                    input.context,
                    input.project,
                    input.primaryProject,
                    input.projectFolder,
                    input.releasesFolder,
                    input.activeCardsFolder,
                    input.runInput.extraPrompt,
                );
        const command = executionCommand(resolvedAgent, providerSession, streaming);
        const contextInput = sourceConversation
            ? normalizeConversationContext(sourceConversation, providerSession?.synchronizedThroughMessageId ?? null)
            : '';
        const reference = input.runInput.continueFrom
            ? continuationReferencePath(input.runInput.continueFrom)
            : input.conversationReservation?.reference;
        const request = {
            actionId: input.action.id,
            agent: resolvedAgent.agent,
            activityOrigin: input.activityOrigin,
            activityProject: input.primaryProject,
            ...(input.context.file ? { cardPath: input.context.file } : {}),
            command,
            ...(sourceConversation ? { conversation: sourceConversation, reference } : {}),
            ...(!sourceConversation && input.conversationReservation
                ? { conversationId: input.conversationReservation.conversationId, reference }
                : {}),
            ...(contextInput ? { contextInput } : {}),
            actionRunId: input.runId,
            prompt,
            projectFolder: input.projectFolder,
            streaming,
            ...(providerSession ? { providerConversationId: providerSession.conversationId } : {}),
            title: input.action.label,
        };
        const fallback = {
            command: resolvedAgent.command,
            contextInput: sourceConversation ? normalizeConversationContext(sourceConversation) : '',
        };
        const result = await this.runAgentTurn(input, request, fallback);
        const executionResult = withoutConversation(result);

        return {
            ...executionResult,
            agent: resolvedAgent.agent,
            model: resolvedAgent.model,
            permissionMode: resolvedAgent.permissionMode,
            thinkingLevel: resolvedAgent.thinkingLevel,
        };
    }

    async runAgentTurn(input, request, fallback) {
        const result = await this.runAgentProcess(input, request);
        if (!request.providerConversationId || !result.missingSession || result.turnStarted) return result;

        const fallbackRequest = {
            ...withoutProviderConversationId(request),
            command: fallback.command,
            conversation: result.conversation,
            ...(fallback.contextInput ? { contextInput: fallback.contextInput } : {}),
            reference: result.reference,
            reuseLastUserMessage: true,
        };

        return this.runAgentProcess(input, fallbackRequest);
    }

    async runAgentProcess(input, request) {
        const { promise, reject, resolve } = Promise.withResolvers();
        const onComplete = (exitCode, run) => resolve({
            command: request.command,
            changedPaths: run.changedPaths ? [...run.changedPaths] : [],
            conversation: run.conversation,
            conversationId: run.conversation.id,
            exitCode,
            missingSession: run.missingSession,
            prompt: request.prompt,
            reference: run.reference,
            stderr: run.stderr,
            stdout: run.stdout,
            queuedMessage: run.queuedMessage?.content ?? null,
            turnStarted: run.turnStarted,
        });
        const onEvent = (agentEvent) => input.onEvent(agentEvent);
        const started = await this.agentRunnerService.start(input.project, request, onEvent, onComplete, reject);
        input.onActiveRunChange(started.runId);

        try {
            if (input.signal.aborted) this.agentRunnerService.stop(started.runId);

            return await promise;
        } finally {
            input.onActiveRunChange(null);
        }
    }
}

module.exports = { ActionAgentExecutor, continuationReferencePath };

