import { useMemo } from 'react'
import { actionContextIdentity } from '../../../../data/action_context'
import {
    actionRunSettingsService,
    createSessionActionRunSettingsStore,
} from '../../../../services/actions/action_run_settings_service'
import { AgentAction } from './agent_action'
import { ActionPopupFrame } from './action_popup_frame'
import { CommandAction } from './command_action'
import { createActionPopupBindings, worktreeValidationMessage } from './action_popup_runtime'
import type { ActionPopupContentProps, ActionPopupRuntime } from './action_popup_types'

export { CARD_RUN_POPUP_SIZE_STORAGE_KEY, PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY } from './action_popup_frame'

/** Selects the action-specific popup content while preserving its runtime for the selected action. */
export function ActionPopupContent(props: ActionPopupContentProps) {
    const { action, assignmentContext } = props
    const settingsContextIdentity = actionContextIdentity(assignmentContext)
    const settingsStore = useMemo(
        () => assignmentContext.cardInternalId
            ? actionRunSettingsService.getCardStore(assignmentContext.cardInternalId, action.id)
            : createSessionActionRunSettingsStore(action.id, settingsContextIdentity),
        [action.id, assignmentContext.cardInternalId, settingsContextIdentity],
    )
    const bindings = useMemo(
        () => createActionPopupBindings(action, assignmentContext),
        [action, assignmentContext],
    )
    const runtime: ActionPopupRuntime = {
        ...bindings,
        runValidationError: worktreeValidationMessage(action, assignmentContext),
        settingsStore,
    }

    return (
        <ActionPopupFrame contentProps={props} conversationStore={bindings.conversationStore}>
            {action.type === 'agent'
                ? (
                    <AgentAction
                        action={action}
                        assignmentContext={assignmentContext}
                        baseContext={props.baseContext}
                        popupEntryId={props.popupEntryId}
                        readOnlyMessage={props.readOnlyMessage}
                        runtime={runtime}
                    />
                ) : (
                    <CommandAction
                        action={action}
                        assignmentContext={assignmentContext}
                        baseContext={props.baseContext}
                        readOnlyMessage={props.readOnlyMessage}
                        runtime={runtime}
                    />
                )}
        </ActionPopupFrame>
    )
}

import type { ActionContext } from '../../../../data/action_context'
import type { ActionDefinition } from '../../../../data/action_types'
import { actionPromptDraftService } from '../../../../services/actions/action_prompt_draft_service'
import { actionRunRegistry } from '../../../../services/actions/action_run_registry'
import type {
    ActionRunSettingsStore,
    ResolvedActionRunSettings,
} from '../../../../services/actions/action_run_settings_service'
import { dataService } from '../../../../services/data/data_service'
import { dialogService } from '../../../../services/dialog_service'
import {
    defaultCancelAction,
    defaultCloseWaitingConversation,
    defaultConvertPromptToAction,
    defaultFinishAction,
    defaultRestartAction,
    defaultRunAction,
} from './action_popup_defaults'
import type { ActionConversationStore } from '../../conversation/action_conversation_store'
import type { ActionHistoryStore } from '../state/action_history_store'
import type { ActionRunInputStore } from '../state/action_run_input_store'
import type { ActionRunResultStore } from '../state/action_run_result_store'

const DEFAULT_CONVERT_LABEL_LENGTH = 40

function hasPersistedSubmittedMessage(
    previousConversation: NonNullable<ReturnType<ActionConversationStore['getSnapshot']>['selectedConversation']>,
    currentConversation: ReturnType<ActionConversationStore['getSnapshot']>['selectedConversation'],
    prompt: string,
) {
    if (!currentConversation || currentConversation.path !== previousConversation.path) return false

    const previousEntryIds = new Set(previousConversation.entries.map(({ id }) => id))

    return currentConversation.entries.some((entry) => entry.kind === 'message'
        && entry.role === 'user'
        && entry.content === prompt
        && !previousEntryIds.has(entry.id))
}

function restorePrompt(action: ActionDefinition, context: ActionContext, prompt: string) {
    const currentRun = currentActionRun(action, context)
    actionPromptDraftService.getDraft(action.id, context, currentRun, { prepare: false }).edit(prompt)
}

export interface ActionPopupOperationInput {
    action: ActionDefinition
    context: ActionContext
    conversationStore: ActionConversationStore
    historyStore: ActionHistoryStore
    inputStore: ActionRunInputStore
    resultStore: ActionRunResultStore
    runValidationError: string | null
    settings: ResolvedActionRunSettings
    settingsStore: ActionRunSettingsStore
}

export function currentActionRun(action: ActionDefinition, context: ActionContext) {
    return actionRunRegistry.getActionRunStore(action.id, context)?.getSnapshot() ?? null
}

export function currentActionPromptDraft(action: ActionDefinition, context: ActionContext, prepare: boolean) {
    const run = currentActionRun(action, context)

    return actionPromptDraftService.getDraft(action.id, context, run, { prepare })
}

async function runWithPrompt(input: ActionPopupOperationInput, prompt: string, previousRunId: string | null = null) {
    const {
        action, context, conversationStore, historyStore, resultStore, runValidationError, settings,
        settingsStore,
    } = input
    resultStore.setRunning()
    try {
        if (runValidationError) throw new Error(runValidationError)

        const liveConversation = currentActionRun(action, context)?.conversation ?? null
        const previousConversation = liveConversation ?? conversationStore.getSnapshot().selectedConversation
        const continuationPath = conversationStore.continuationPath(liveConversation)
        const runInput = action.type === 'agent'
            ? {
                ...(settings.agent ? { agent: settings.agent } : {}),
                ...(continuationPath ? { continueFrom: continuationPath } : {}),
                prompt,
                ...(settings.model ? { model: settings.model } : {}),
                ...(settings.permissionMode ? { permissionMode: settings.permissionMode } : {}),
                thinkingLevel: settings.thinkingLevel,
            }
            : { extraPrompt: prompt }
        const handleStarted = (runId: string) => {
            resultStore.setRunId(runId)
            settingsStore.markSettingsApplied()
            actionPromptDraftService.clearDraft(action.id, context, currentActionRun(action, context))
        }
        const result = previousRunId
            ? await defaultRestartAction(previousRunId, action, context, runInput, handleStarted)
            : await defaultRunAction(action, context, runInput, handleStarted)
        resultStore.setResult(result)
        await historyStore.load()
        if (action.type === 'agent') {
            await conversationStore.load()
            if (previousRunId
                && result.status === 'failed'
                && previousConversation
                && !hasPersistedSubmittedMessage(
                    previousConversation,
                    conversationStore.getSnapshot().selectedConversation,
                    prompt,
                )) {
                restorePrompt(action, context, prompt)
            }
        }
    } catch (error) {
        if (previousRunId) restorePrompt(action, context, prompt)
        const message = error instanceof Error ? error.message : 'Action run failed'
        resultStore.setResult({
            logs: [{
                actionId: action.id,
                actionName: action.label,
                command: null,
                message,
                phase: 'main',
                status: 'failed',
                stderr: message,
                stdout: '',
            }],
            status: 'failed',
        })
        dialogService.error(error, { fallbackMessage: 'Action run failed' })
    }
}

export async function runPopupAction(input: ActionPopupOperationInput) {
    const { action, context, settingsStore } = input
    const run = currentActionRun(action, context)
    const promptDraft = actionPromptDraftService.getDraft(action.id, context, run, { prepare: false })
    const prompt = promptDraft.getSnapshot()
    const sessionActive = run?.status === 'queued' || run?.status === 'running' || run?.status === 'waitingForInput'
    const agentActive = sessionActive && run?.activeActionType === 'agent'

    if (agentActive && run) {
        if (run.question || run.approvals.length) return
        if (run.status === 'waitingForInput' && settingsStore.getSnapshot().settingsChangedWhileWaiting) {
            await runWithPrompt(input, prompt, run.runId)
            return
        }
        try {
            if (run.activeActionStreaming) await promptDraft.send()
            else {
                await promptDraft.synchronize()
                actionPromptDraftService.clearDraft(action.id, context, run)
            }
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not send agent message' })
        }
        return
    }

    await runWithPrompt(input, prompt)
}

export async function convertPromptToAction(input: ActionPopupOperationInput) {
    const { action, context, inputStore, settings } = input
    const prompt = currentActionPromptDraft(action, context, false).getSnapshot()
    const { actionLabel } = inputStore.getSnapshot()
    inputStore.setConvertMessage(null)
    try {
        const label = actionLabel.trim().length > 0 ? actionLabel : prompt.trim().slice(0, DEFAULT_CONVERT_LABEL_LENGTH)
        const convertInput = {
            ...(settings.agent ? { agent: settings.agent } : {}),
            context,
            label,
            ...(settings.model ? { model: settings.model } : {}),
            ...(settings.permissionMode ? { permissionMode: settings.permissionMode } : {}),
            prompt,
        }
        const result = await defaultConvertPromptToAction(convertInput)
        inputStore.setConvertMessage(`Saved ${result.path}`)

        return true
    } catch (error) {
        inputStore.setConvertMessage(error instanceof Error ? error.message : 'Could not convert prompt to action')

        return false
    }
}

export async function saveAndRunPopupAction(input: ActionPopupOperationInput) {
    if (!await convertPromptToAction(input)) return

    await runPopupAction(input)
}

async function closeWaitingConversation(
    action: ActionDefinition,
    context: ActionContext,
    conversationStore: ActionConversationStore,
    status: 'cancelled' | 'completed',
) {
    const conversation = conversationStore.getSnapshot().selectedConversation
    if (!conversation) throw new Error('No agent conversation is selected')
    if (conversation.status !== 'waitingForInput') throw new Error('Selected agent conversation is no longer waiting for input')

    const updatedConversation = await defaultCloseWaitingConversation(conversation.path, status)
    conversationStore.updateConversation(updatedConversation)
    dataService.agents.updateAgentConversation(updatedConversation)
    actionPromptDraftService.clearDraft(action.id, context, null)
}

export async function cancelPopupAction(
    action: ActionDefinition,
    context: ActionContext,
    conversationStore: ActionConversationStore,
) {
    const run = currentActionRun(action, context)
    const sessionActive = run?.status === 'queued' || run?.status === 'running' || run?.status === 'waitingForInput'
    if (!run || !sessionActive) {
        try {
            await closeWaitingConversation(action, context, conversationStore, 'cancelled')
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not stop waiting agent conversation' })
        }
        return
    }

    await defaultCancelAction(run.runId)
    actionPromptDraftService.clearDraft(action.id, context, run)
}

export async function finishPopupAction(
    action: ActionDefinition,
    context: ActionContext,
    conversationStore: ActionConversationStore,
) {
    const run = currentActionRun(action, context)
    const sessionActive = run?.status === 'queued' || run?.status === 'running' || run?.status === 'waitingForInput'
    if (!run || !sessionActive) {
        try {
            await closeWaitingConversation(action, context, conversationStore, 'completed')
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Could not finish waiting agent conversation' })
        }
        return
    }

    try {
        await defaultFinishAction(run.runId)
        actionPromptDraftService.clearDraft(action.id, context, run)
    } catch (error) {
        dialogService.error(error, { fallbackMessage: 'Could not finish agent session' })
    }
}

const ALLOWED_REQUEST_FIELDS = new Set(['actionId', 'context', 'conversationReservation', 'runInput']);
const ALLOWED_RUN_INPUT_FIELDS = new Set(['agent', 'continueFrom', 'extraPrompt', 'model', 'permissionMode', 'prompt', 'thinkingLevel']);
const CONTEXT_KINDS = new Set(['card', 'file', 'folder', 'merge-conflict', 'project']);

function readOptionalString(value, fieldName) {
    if (value === undefined) return undefined;
    if (typeof value !== 'string') throw new Error(`Invalid action run input ${fieldName}`);

    return value;
}

function readPrompt(runInput) {
    if (!Object.hasOwn(runInput, 'prompt')) return {};
    if (typeof runInput.prompt !== 'string') throw new Error('Invalid action run input prompt');

    return { prompt: runInput.prompt };
}

function validateContext(context) {
    if (!context || typeof context !== 'object' || Array.isArray(context)) throw new Error('Missing action context');
    if (!CONTEXT_KINDS.has(context.kind)) throw new Error('Invalid action context kind');

    for (const [fieldName, value] of Object.entries(context)) {
        if (value !== undefined && typeof value !== 'string') throw new Error(`Invalid action context field ${fieldName}`);
    }

    return { ...context };
}

function validateRunInput(runInput = {}) {
    if (!runInput || typeof runInput !== 'object' || Array.isArray(runInput)) throw new Error('Invalid action runInput');

    const unsupportedField = Object.keys(runInput).find((fieldName) => !ALLOWED_RUN_INPUT_FIELDS.has(fieldName));
    if (unsupportedField) throw new Error(`Unsupported action runInput field: ${unsupportedField}`);

    return {
        agent: readOptionalString(runInput.agent, 'agent'),
        continueFrom: readOptionalString(runInput.continueFrom, 'continueFrom'),
        extraPrompt: readOptionalString(runInput.extraPrompt, 'extraPrompt') ?? '',
        model: readOptionalString(runInput.model, 'model'),
        permissionMode: readOptionalString(runInput.permissionMode, 'permissionMode'),
        ...readPrompt(runInput),
        thinkingLevel: readOptionalString(runInput.thinkingLevel, 'thinkingLevel'),
    };
}

function validateConversationReservation(reservation) {
    if (reservation === undefined) return undefined;
    if (!reservation || typeof reservation !== 'object' || Array.isArray(reservation)) {
        throw new Error('Invalid agent conversation reservation');
    }
    const allowedFields = new Set(['conversationId', 'reference']);
    const unsupportedField = Object.keys(reservation).find((fieldName) => !allowedFields.has(fieldName));
    if (unsupportedField) throw new Error(`Unsupported agent conversation reservation field: ${unsupportedField}`);
    if (typeof reservation.conversationId !== 'string' || reservation.conversationId.length === 0) {
        throw new Error('Missing reserved agent conversationId');
    }
    if (typeof reservation.reference !== 'string' || reservation.reference.length === 0) {
        throw new Error('Missing reserved agent conversation reference');
    }

    return { conversationId: reservation.conversationId, reference: reservation.reference };
}

function validateStartRequest(request) {
    if (!request || typeof request !== 'object' || Array.isArray(request)) throw new Error('Missing action start request');

    const unsupportedField = Object.keys(request).find((fieldName) => !ALLOWED_REQUEST_FIELDS.has(fieldName));
    if (unsupportedField) throw new Error(`Unsupported action start field: ${unsupportedField}`);
    if (typeof request.actionId !== 'string' || request.actionId.length === 0) throw new Error('Missing actionId');

    const conversationReservation = validateConversationReservation(request.conversationReservation);

    return {
        actionId: request.actionId,
        ...(conversationReservation ? { conversationReservation } : {}),
        context: validateContext(request.context),
        runInput: validateRunInput(request.runInput),
    };
}

function validatePreparePromptRequest(request) {
    if (!request || typeof request !== 'object' || Array.isArray(request)) throw new Error('Missing action prompt request');
    const allowedFields = new Set(['actionId', 'context']);
    const unsupportedField = Object.keys(request).find((fieldName) => !allowedFields.has(fieldName));
    if (unsupportedField) throw new Error(`Unsupported action prompt field: ${unsupportedField}`);
    if (typeof request.actionId !== 'string' || request.actionId.length === 0) throw new Error('Missing actionId');

    return { actionId: request.actionId, context: validateContext(request.context) };
}

module.exports = { validatePreparePromptRequest, validateStartRequest };

import type { ActionContext } from '../../data/action_context'
import type { ActionDefinition } from '../../data/action_types'
import type { AgentConversationReservation, ActionRunInput, ActionRunResult } from '../../data/action_run_types'
import { getElectronActionBridge } from '../../data/electron_action_bridge'
import { actionRunRegistry, cancelActionRun } from './action_run_registry'
import { dataService } from '../data/data_service'
import { projectPersistenceService } from '../project/project_persistence_service'
import { projectAccessService } from '../project/project_access_service'

function shouldReserveConversation(action: ActionDefinition, context: ActionContext, input: ActionRunInput) {
    return action.type === 'agent'
        && !input.continueFrom
        && (context.kind === 'card' || context.kind === 'file')
        && !!context.cardInternalId
        && !!context.file
}

/** Start one persisted action through shared renderer run state. */
export async function runElectronAction(
    action: ActionDefinition,
    context: ActionContext,
    input: ActionRunInput = {},
    onStarted?: (runId: string) => void,
    interactive = true,
): Promise<ActionRunResult> {
    projectAccessService.requireWritable()
    const handleStarted = (startedRunId: string) => {
        onStarted?.(startedRunId)
    }
    const requiresReservation = shouldReserveConversation(action, context, input)
    const bridge = getElectronActionBridge()
    const resumeAutomaticCommit = requiresReservation ? dataService.cards.deferAutomaticCommit() : null
    let conversationReservation: AgentConversationReservation | undefined
    try {
        conversationReservation = requiresReservation
            ? await bridge?.reserveActionConversation?.({ actionId: action.id, context, runInput: input })
            : undefined
        if (requiresReservation && !conversationReservation) {
            throw new Error('Starting a card agent requires conversation reservation support')
        }
        if (conversationReservation && context.file) {
            dataService.cards.addAgentLogReference(context.file, conversationReservation.reference)
        }
    } finally {
        resumeAutomaticCommit?.()
    }
    if (projectPersistenceService.getSnapshot().hasPendingSave) await projectPersistenceService.flushPendingChanges()
    return actionRunRegistry.startRun(action, context, input, handleStarted, interactive, conversationReservation)
}

/** Finish one idle streaming run, persist it, then continue through a new process. */
export async function restartElectronAction(
    previousRunId: string,
    action: ActionDefinition,
    context: ActionContext,
    input: ActionRunInput,
    onStarted?: (runId: string) => void,
): Promise<ActionRunResult> {
    projectAccessService.requireWritable()
    if (projectPersistenceService.getSnapshot().hasPendingSave) await projectPersistenceService.flushPendingChanges()

    return actionRunRegistry.restartRun(previousRunId, action, context, input, onStarted)
}

export async function cancelElectronAction(runId: string) {
    await cancelActionRun(runId)
}

const { ActionCancellationError } = require('./action_cancellation_error');
const { executeCommandAction } = require('./action_command_executor');
const { ActionPhaseError } = require('./action_phase_error');
const { runWithGitOperationContext } = require('../../git/git_operation_context');
const {
    captureCommitReferences,
    combineOutput,
    createAgentDetails,
    createCommandDetails,
} = require('./action_run_history');

function errorMessage(error, fallback) {
    return error instanceof Error ? error.message : fallback;
}

class ActionRun {
    constructor(snapshot, dependencies) {
        this.actionsFolder = snapshot.actionsFolder;
        this.activeCardsFolder = snapshot.activeCardsFolder;
        this.activityOrigin = snapshot.activityOrigin;
        this.context = snapshot.context;
        this.conversationReservation = snapshot.conversationReservation;
        this.runId = snapshot.runId;
        this.project = snapshot.project;
        this.projectFolder = snapshot.projectFolder;
        this.releasesFolder = snapshot.releasesFolder;
        this.rootAction = snapshot.rootAction;
        this.runInput = snapshot.runInput;
        this.startedAt = snapshot.startedAt;
        this.actionWorktreeRunService = dependencies.actionWorktreeRunService;
        this.agentExecutor = dependencies.agentExecutor;
        this.agentRunnerService = dependencies.agentRunnerService;
        this.commandRunner = dependencies.commandRunner;
        this.localGitService = dependencies.localGitService;
        this.publisher = dependencies.publisher;
        this.activeAction = null;
        this.activeAgentRunId = null;
        this.activeAgentQuestion = false;
        this.activeAgentApprovals = new Map();
        this.autoFinishPending = false;
        this.commitReferenceKeys = new Set();
        this.commitReferences = [];
        this.conversationIds = [];
        this.completion = null;
        this.controller = new AbortController();
        this.rootDetails = null;
        this.rootConversationId = null;
        this.nextEventSequence = 1;
    }

    start(finalize) {
        const runCompletion = this.run();
        this.completion = finalize(runCompletion);
    }

    cancel() {
        this.controller.abort();
        if (this.activeAgentRunId) this.agentRunnerService.stop(this.activeAgentRunId);
    }

    suspend() {
        this.controller.abort();
        if (this.activeAgentRunId) this.agentRunnerService.suspend(this.activeAgentRunId);
    }

    sendAgentMessage(content) {
        if (!this.activeAgentRunId) throw new Error(`Action run has no active streaming agent: ${this.runId}`);
        if (this.activeAgentQuestion) throw new Error('Answer pending structured question before sending queued prompt');
        if (this.activeAgentApprovals.size > 0) throw new Error('Answer pending approval before sending queued prompt');
        return this.agentRunnerService.sendMessage(this.activeAgentRunId, content);
    }

    beginAgentPromptDraft() {
        if (!this.activeAgentRunId) throw new Error(`Action run has no active agent: ${this.runId}`);

        return this.agentRunnerService.beginQueuedMessageDraft(this.activeAgentRunId);
    }

    setAgentQueuedMessage(sessionId, content, revision) {
        if (!this.activeAgentRunId) throw new Error(`Action run has no active agent: ${this.runId}`);

        return this.agentRunnerService.setQueuedMessage(this.activeAgentRunId, sessionId, content, revision);
    }

    sendQueuedAgentMessage(sessionId, revision) {
        if (!this.activeAgentRunId) throw new Error(`Action run has no active agent: ${this.runId}`);
        if (this.activeAgentQuestion) throw new Error('Answer pending structured question before sending queued prompt');
        if (this.activeAgentApprovals.size > 0) throw new Error('Answer pending approval before sending queued prompt');
        return this.agentRunnerService.sendQueuedMessage(this.activeAgentRunId, sessionId, revision);
    }

    async answerAgentQuestion(requestId, answers) {
        if (!this.activeAgentRunId) throw new Error(`Action run has no active streaming agent: ${this.runId}`);
        await this.agentRunnerService.answerQuestion(this.activeAgentRunId, requestId, answers);
        this.activeAgentQuestion = false;
    }

    answerAgentApproval(requestId, decision) {
        if (!this.activeAgentRunId) throw new Error(`Action run has no active streaming agent: ${this.runId}`);
        if (!this.activeAgentApprovals.has(requestId)) throw new Error(`Unknown or stale action approval request id: ${requestId}`);

        return this.agentRunnerService.answerApproval(this.activeAgentRunId, requestId, decision);
    }

    finishAgent() {
        if (!this.activeAgentRunId) throw new Error(`Action run has no active streaming agent: ${this.runId}`);
        this.agentRunnerService.finish(this.activeAgentRunId);
    }

    handleCardStateChange(cardInternalId, state) {
        if (this.context.cardInternalId !== cardInternalId) return;
        if (
            this.activeAction?.type !== 'agent'
            || !this.activeAction.streaming
            || this.activeAction.autoFinish?.state !== state
        ) return;
        if (this.activeAgentRunId) {
            this.agentRunnerService.finish(this.activeAgentRunId);
            return;
        }

        this.autoFinishPending = true;
    }

    async run() {
        return runWithGitOperationContext({ runId: this.runId }, () => this.runWithContext());
    }

    async runWithContext() {
        this.publish(this.rootAction, 'main', 'running', { type: 'run' });
        let status = 'completed';
        let failure = null;
        try {
            const onQueued = () => this.publish(this.rootAction, 'main', 'queued', { type: 'action' });
            const lockOptions = { onQueued, signal: this.controller.signal };
            await this.actionWorktreeRunService.runWithCardLock(
                this.project,
                this.context,
                () => this.runAction(this.rootAction, 'main', true),
                lockOptions,
            );
        } catch (error) {
            failure = error;
            if (error instanceof ActionCancellationError || this.controller.signal.aborted) status = 'cancelled';
            else status = error instanceof ActionPhaseError && error.rootPhase === 'after' ? 'okButNotAfter' : 'failed';
        }

        try {
            await this.persistRootActivity(status, failure);
        } catch (error) {
            failure = error;
            status = 'failed';
            const message = errorMessage(error, `${this.rootAction.label} history recording failed`);
            this.publish(this.rootAction, 'main', 'failed', { message, type: 'action' });
        }

        const result = {
            runId: this.runId,
            failure: failure ? errorMessage(failure, 'Action failed') : null,
            status,
        };
        this.publish(this.rootAction, 'main', status, { message: result.failure, type: 'run' });

        return result;
    }

    async runAction(action, phase, isRoot = false, rootPhase = phase) {
        this.throwIfCancelled();
        for (const beforeAction of action.onBefore) {
            await this.runAction(beforeAction, 'before', false, isRoot ? 'before' : rootPhase);
        }

        const output = await this.runMain(action, phase, isRoot, rootPhase);
        const matches = action.on.filter((rule) => new RegExp(rule.condition, 'u').test(output));
        for (const rule of matches) await this.runAction(rule.action, 'on', false, isRoot ? 'on' : rootPhase);

        for (const afterAction of action.onAfter) {
            await this.runAction(afterAction, 'after', false, isRoot ? 'after' : rootPhase);
        }

        return output;
    }

    async runMain(action, phase, isRoot, rootPhase) {
        this.throwIfCancelled();
        this.activeAction = action;
        this.autoFinishPending = false;

        try {
            const result = await this.executeAction(action, phase, isRoot);
            if (this.controller.signal.aborted) {
                this.publish(action, phase, 'cancelled', {
                    command: Array.isArray(result.command) ? result.command.join(' ') : result.command,
                    runWorktree: result.runWorktree,
                    message: 'Action cancelled',
                    permissionMode: result.permissionMode,
                    reference: result.reference,
                    conversationId: result.conversationId,
                    thinkingLevel: result.thinkingLevel,
                    type: 'action',
                });
                const cancellationError = new ActionCancellationError('Action cancelled');
                cancellationError.terminalEventEmitted = true;
                throw cancellationError;
            }

            const status = result.exitCode === 0 ? 'completed' : 'failed';
            const output = combineOutput(result);
            this.publish(action, phase, status, {
                command: Array.isArray(result.command) ? result.command.join(' ') : result.command,
                runWorktree: result.runWorktree,
                message: status === 'completed' ? `${action.label} completed` : `${action.label} failed with exit code ${result.exitCode}`,
                permissionMode: result.permissionMode,
                reference: result.reference,
                conversationId: result.conversationId,
                thinkingLevel: result.thinkingLevel,
                type: 'action',
            });
            this.clearActiveAction(action);
            if (result.exitCode !== 0) throw new ActionPhaseError(`${action.label} failed with exit code ${result.exitCode}`, phase, rootPhase);

            return output;
        } catch (error) {
            this.clearActiveAction(action);
            if (error instanceof ActionCancellationError || this.controller.signal.aborted) {
                if (!error?.terminalEventEmitted) this.publish(action, phase, 'cancelled', { message: 'Action cancelled', type: 'action' });
                throw new ActionCancellationError('Action cancelled');
            }
            if (error instanceof ActionPhaseError) throw error;

            const message = errorMessage(error, `${action.label} failed`);
            this.publish(action, phase, 'failed', { message, type: 'action' });
            throw new ActionPhaseError(message, phase, rootPhase, error);
        }
    }

    clearActiveAction(action) {
        if (this.activeAction !== action) return;
        this.activeAction = null;
        this.autoFinishPending = false;
    }

    async executeAction(action, phase, isRoot) {
        if (action.type === 'command' && isRoot && this.runInput.continueFrom) {
            throw new Error('Conversation continuation requires an agent action');
        }
        if (action.autoFinish && (
            this.context.kind !== 'card'
            || typeof this.context.cardInternalId !== 'string'
            || this.context.cardInternalId.length === 0
        )) {
            throw new Error(`Action "${action.label}" requires card context for autoFinish`);
        }

        return this.actionWorktreeRunService.execute(this.project, action, this.context, async (project) => {
            this.publish(action, phase, 'running', { type: 'action' });
            const result = action.type === 'agent'
                ? await this.executeAgentAction(action, phase, isRoot, project)
                : await this.executeCommandAction(action, phase, isRoot, project);
            const committedResult = await this.commitTrackedAgentChanges(project, action, result);
            const runProject = {
                ...project,
                branch: committedResult.branch ?? project.branch,
                rootPath: committedResult.repositoryRoot ?? project.rootPath,
            };
            const historyInput = {
                action,
                context: this.context,
                project: runProject,
                projectFolder: this.projectFolder,
                result: committedResult,
            };
            const details = action.type === 'agent'
                ? createAgentDetails(historyInput)
                : createCommandDetails(historyInput);
            const commitReferences = await captureCommitReferences(this.localGitService, historyInput);
            this.collectCommitReferences(commitReferences);
            if (isRoot) {
                this.rootDetails = details;
                if (action.type === 'agent') this.rootConversationId = committedResult.conversationId;
            }
            if (action.type === 'agent' && typeof committedResult.conversationId === 'string') {
                this.conversationIds.push(committedResult.conversationId);
            }

            return committedResult;
        });
    }

    collectCommitReferences(references) {
        for (const reference of references) {
            const key = `${reference.repositoryRoot}\0${reference.commit}`;
            if (this.commitReferenceKeys.has(key)) continue;
            this.commitReferenceKeys.add(key);
            this.commitReferences.push(reference);
        }
    }

    async persistRootActivity(status, failure) {
        const completedAt = new Date().toISOString();
        const commits = this.commitReferences.map((reference) => {
            const persisted = Object.fromEntries(Object.entries(reference).filter(([fieldName]) => fieldName !== 'repositoryRoot'));
            if (reference.actionId === this.rootAction.id) {
                delete persisted.actionId;
                delete persisted.actionName;
            }

            return persisted;
        });
        if (this.rootAction.type === 'agent' && typeof this.rootConversationId !== 'string') {
            return;
        }
        const details = this.rootDetails ?? {
            command: this.rootAction.command,
            output: failure ? errorMessage(failure, 'Action failed') : '',
            type: 'command',
        };
        const record = {
            commits,
            completedAt,
            conversationIds: [...new Set(this.conversationIds)],
            details,
            runId: this.runId,
            origin: this.activityOrigin,
            rootActionId: this.rootAction.id,
            rootActionLabel: this.rootAction.label,
            ...(this.rootConversationId ? { rootConversationId: this.rootConversationId } : {}),
            startedAt: this.startedAt,
            status,
        };
        await this.localGitService.appendAndCommitActionActivity(
            this.project,
            this.projectFolder,
            this.activityOrigin,
            record,
            `Record ${this.rootAction.label} activity`,
        );
    }

    async commitTrackedAgentChanges(project, action, result) {
        if (action.type !== 'agent' || !action.trackFileChanges) return result;
        if (result.exitCode !== 0 || this.controller.signal.aborted) return result;
        const changedPaths = result.changedPaths ?? [];
        if (changedPaths.length === 0) return result;
        const trackedCommit = await this.localGitService.commitTrackedPaths(
            project.rootPath,
            changedPaths,
            action.label,
            this.controller.signal,
        );

        return { ...result, trackedCommit };
    }

    executeCommandAction(action, phase, isRoot, project) {
        const onOutput = ({ command, stderr, stdout }) => {
            if (stdout.length > 0) this.publish(action, phase, 'running', { type: 'update', update: { command, content: stdout, kind: 'output' } });
            if (stderr.length > 0) this.publish(action, phase, 'running', { type: 'update', update: { command, content: stderr, kind: 'error' } });
        };

        return executeCommandAction({
            action,
            activeCardsFolder: this.activeCardsFolder,
            commandRunner: this.commandRunner,
            context: this.context,
            extraPrompt: isRoot ? this.runInput.extraPrompt : '',
            onOutput,
            primaryProject: this.project,
            project,
            projectFolder: this.projectFolder,
            releasesFolder: this.releasesFolder,
            signal: this.controller.signal,
        });
    }

    async executeAgentAction(action, phase, isRoot, project) {
        const onActiveRunChange = (runId) => {
            this.activeAgentRunId = runId;
            if (runId) {
                this.publish(action, phase, 'running', { interactionReady: true, type: 'agentState' });
                if (this.autoFinishPending) {
                    this.autoFinishPending = false;
                    this.agentRunnerService.finish(runId);
                }
            }
            else {
                this.activeAgentQuestion = false;
                this.activeAgentApprovals.clear();
                this.publish(action, phase, 'running', { interactionReady: false, type: 'agentState' });
            }
        };
        const onEvent = (agentEvent) => {
            if (agentEvent.type === 'started') {
                const { continued, conversation } = agentEvent;
                const update = { continued, conversation, kind: 'agentStarted' };
                this.publish(action, phase, 'running', { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'closed') {
                const update = { conversation: agentEvent.conversation, kind: 'agentClosed' };
                this.publish(action, phase, agentEvent.conversation.status, { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'state') {
                this.publish(action, phase, agentEvent.state, { interactionReady: true, type: 'agentState' });
                return;
            }
            if (agentEvent.type === 'question') {
                this.activeAgentQuestion = true;
                const update = {
                    kind: 'agentQuestion',
                    questions: agentEvent.questions,
                    requestId: agentEvent.requestId,
                };
                this.publish(action, phase, 'waitingForInput', { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'userMessage') {
                this.activeAgentQuestion = false;
                const update = { kind: 'agentUserMessage', userMessage: agentEvent.userMessage };
                this.publish(action, phase, 'running', { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'questionAnswered') {
                this.activeAgentQuestion = false;
                const update = { kind: 'agentQuestionAnswer', userMessage: agentEvent.userMessage };
                this.publish(action, phase, agentEvent.state, { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'approval') {
                this.activeAgentApprovals.set(agentEvent.approval.requestId, { ...agentEvent.approval, submitted: false });
                const update = { approval: agentEvent.approval, kind: 'agentApproval' };
                this.publish(action, phase, 'waitingForInput', { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'approvalSubmitted') {
                const approval = this.activeAgentApprovals.get(agentEvent.requestId);
                if (!approval) return;
                approval.submitted = true;
                const update = { kind: 'agentApprovalSubmitted', requestId: agentEvent.requestId };
                this.publish(action, phase, 'waitingForInput', { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'approvalResolved') {
                if (!this.activeAgentApprovals.delete(agentEvent.requestId)) return;
                const update = { kind: 'agentApprovalResolved', requestId: agentEvent.requestId };
                this.publish(action, phase, agentEvent.state, { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'agentEvent') {
                const update = { event: agentEvent.event, kind: 'agentEvent' };
                this.publish(action, phase, 'running', { type: 'update', update });
                return;
            }
            if (agentEvent.type === 'usage') {
                const update = {
                    ...(agentEvent.contextWindowUsage !== undefined
                        ? { contextWindowUsage: agentEvent.contextWindowUsage }
                        : {}),
                    kind: 'agentUsage',
                    usage: agentEvent.usage,
                };
                this.publish(action, phase, 'running', { type: 'update', update });
                return;
            }

            const update = {
                content: agentEvent.content,
                kind: agentEvent.type,
                ...(agentEvent.messageId !== undefined ? { messageId: agentEvent.messageId } : {}),
                ...(agentEvent.previousContent !== undefined ? { previousContent: agentEvent.previousContent } : {}),
                ...(agentEvent.replace !== undefined ? { replace: agentEvent.replace } : {}),
                ...(agentEvent.sequence !== undefined ? { sequence: agentEvent.sequence } : {}),
            };
            this.publish(action, phase, 'running', { type: 'update', update });
        };
        const runInput = isRoot ? this.runInput : { extraPrompt: '' };

        const input = {
            action,
            activeCardsFolder: this.activeCardsFolder,
            activityOrigin: this.activityOrigin,
            context: this.context,
            conversationReservation: isRoot ? this.conversationReservation : null,
            runId: this.runId,
            onActiveRunChange,
            onEvent,
            project,
            projectFolder: this.projectFolder,
            primaryProject: this.project,
            releasesFolder: this.releasesFolder,
            runInput,
            signal: this.controller.signal,
        };
        let result = await this.agentExecutor.execute(input);
        const changedPaths = new Set(result.changedPaths ?? []);
        let stderr = result.stderr ?? '';
        let stdout = result.stdout ?? '';
        while (result.exitCode === 0 && result.queuedMessage) {
            const queuedMessage = result.queuedMessage;
            result = await this.agentExecutor.execute({
                ...input,
                runInput: {
                    ...runInput,
                    continueFrom: result.reference,
                    prompt: queuedMessage,
                },
            });
            for (const changedPath of result.changedPaths ?? []) changedPaths.add(changedPath);
            stderr += result.stderr ?? '';
            stdout += result.stdout ?? '';
        }

        return { ...result, changedPaths: [...changedPaths], stderr, stdout };
    }

    publish(action, phase, status, details) {
        const event = {
            actionId: action.id,
            actionType: action.type,
            autoFinish: action.autoFinish ?? null,
            context: this.context,
            runId: this.runId,
            interactionReady: details.interactionReady ?? false,
            phase,
            rootActionId: this.rootAction.id,
            status,
            streaming: action.type === 'agent' && action.streaming,
            ...details,
            sequence: this.nextEventSequence,
        };
        this.nextEventSequence += 1;
        this.publisher(event);
    }

    throwIfCancelled() {
        if (this.controller.signal.aborted) throw new ActionCancellationError('Action cancelled');
    }
}

